import { describe, expect, test } from "bun:test";
import { greet, add, slugify } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

describe("slugify", () => {
  test("REQ-001: converts uppercase to lowercase", () => {
    expect(slugify("Hello")).toBe("hello");
    expect(slugify("ABC123")).toBe("abc123");
    expect(slugify("FooBar")).toBe("foobar");
  });

  test("REQ-002: replaces single space with hyphen", () => {
    expect(slugify("a b")).toBe("a-b");
    expect(slugify("hello world")).toBe("hello-world");
  });

  test("REQ-002: replaces multiple spaces with single hyphen", () => {
    expect(slugify("a  b")).toBe("a-b");
    expect(slugify("a   b")).toBe("a-b");
  });

  test("REQ-002: replaces underscores with hyphens", () => {
    expect(slugify("a_b")).toBe("a-b");
    expect(slugify("test_case")).toBe("test-case");
  });

  test("REQ-002: replaces double underscores with single hyphen", () => {
    expect(slugify("a__b")).toBe("a-b");
    expect(slugify("Foo__Bar")).toBe("foo-bar");
  });

  test("REQ-003: removes special characters", () => {
    expect(slugify("a!b")).toBe("ab");
    expect(slugify("Hello, World!")).toBe("hello-world");
    expect(slugify("a.b.c")).toBe("abc");
    expect(slugify("can't")).toBe("cant");
  });

  test("REQ-004: deduplicates consecutive hyphens", () => {
    expect(slugify("a--b")).toBe("a-b");
    expect(slugify("a---b")).toBe("a-b");
  });

  test("REQ-005: trims leading hyphens", () => {
    expect(slugify("-hello")).toBe("hello");
    expect(slugify("--hello")).toBe("hello");
  });

  test("REQ-005: trims trailing hyphens", () => {
    expect(slugify("hello-")).toBe("hello");
    expect(slugify("hello--")).toBe("hello");
  });

  test("REQ-005: trims both leading and trailing hyphens", () => {
    expect(slugify("-hello-")).toBe("hello");
    expect(slugify("--hello--")).toBe("hello");
  });

  test("handles empty string", () => {
    expect(slugify("")).toBe("");
  });

  test("handles all special characters", () => {
    expect(slugify("---")).toBe("");
    expect(slugify("!!!")).toBe("");
  });

  test("handles complex mixed input", () => {
    expect(slugify("Foo__Bar  ")).toBe("foo-bar");
    expect(slugify("  spaces  ")).toBe("spaces");
  });

  test("preserves interior hyphens", () => {
    expect(slugify("hello-world")).toBe("hello-world");
  });
});

